  content = '{"level_id":"7.8","badge_name":"আইন কি বলে?","level_title":"পরিবেশগত আইন: আমাদের দায়িত্ব","mission_briefing":"একজন লাইনম্যান হিসেবে আপনার দায়িত্ব শুধু মানুষ বা যন্ত্রপাতির সুরক্ষার মধ্যেই সীমাবদ্ধ নয়। আপনার কাজের পরিবেশের ওপরও একটি প্রভাব পড়ে। পুরনো ট্রান্সফরমার অয়েল, ব্যবহৃত ব্যাটারি বা রাসায়নিক—এগুলো যদি সঠিক উপায়ে নিষ্পত্তি বা ডিসপোজ না করা হয়, তবে তা মাটি এবং জলকে দূষিত করতে পারে। এই লেভেলের মিশন হলো, আপনার কাজের সাথে জড়িত পরিবেশগত আইনগুলো সম্পর্কে জানা এবং একজন পরিবেশ-সচেতন কারিগর হয়ে ওঠা।","sections":[{"title":"পরিবেশ রক্ষায় আপনার ভূমিকা","points":[{"item_name":"১. ট্রান্সফরমার অয়েল: একটি বিপজ্জনক বর্জ্য","specifications":"পুরনো বা ব্যবহৃত ট্রান্সফরমার অয়েলকে ''বিপজ্জনক বর্জ্য'' বা ''Hazardous Waste'' হিসেবে গণ্য করা হয়, কারণ এর মধ্যে PCB (Polychlorinated Biphenyls)-এর মতো ক্ষতিকারক রাসায়নিক থাকতে পারে।\n• আইন: ''Hazardous Waste Management Rules'' অনুযায়ী, এই তেল মাটিতে বা ড্রেনে ফেলা একটি দণ্ডনীয় অপরাধ।\n• করণীয়: তেল বদলানোর সময়, পুরনো তেলটি একটি লিক-প্রুফ ড্রামে সংগ্রহ করতে হবে এবং সেটিকে শুধুমাত্র অনুমোদিত রিসাইক্লিং এজেন্সির কাছে হস্তান্তর করতে হবে।","importance":"এক লিটার তেল লক্ষ লক্ষ লিটার জলকে দূষিত করতে পারে। এর সঠিক নিষ্পত্তি আমাদের পরিবেশকে বাঁচানোর জন্য অপরিহার্য।","image_name":"/images/loader/haz78_oil.webp","image_caption":"ট্রান্সফরমার অয়েল · বর্জ্য"},{"item_name":"২. পুরনো ব্যাটারি এবং ইলেকট্রনিক বর্জ্য (E-waste)","specifications":"কন্ট্রোল প্যানেল বা অন্যান্য যন্ত্রের পুরনো ব্যাটারির মধ্যে সীসা (Lead) এবং অ্যাসিডের মতো ক্ষতিকারক পদার্থ থাকে।\n• আইন: ''E-waste (Management) Rules'' অনুযায়ী, এই ধরনের বর্জ্য সাধারণ ময়লার সাথে ফেলা যাবে না।\n• করণীয়: পুরনো ব্যাটারি এবং অন্যান্য ইলেকট্রনিক যন্ত্রাংশ (যেমন খারাপ সার্কিট বোর্ড) কোম্পানির নির্ধারিত সংগ্রহ কেন্দ্রে জমা দিতে হবে।","importance":"ই-ওয়েস্ট মাটির নিচে মিশে গিয়ে ক্ষতিকারক রাসায়নিক নির্গত করে, যা আমাদের খাদ্য এবং জলের মাধ্যমে শরীরে প্রবেশ করতে পারে।","image_name":"/images/loader/haz78_battery.webp","image_caption":"ব্যাটারি · ই-ওয়েস্ট"},{"item_name":"৩. পুরনো ল্যাম্প এবং পারদ (Mercury)","specifications":"পুরনো ফ্লুরোসেন্ট টিউব লাইট, সিএফএল (CFL) বা সোডিয়াম/মার্কারি ভেপার ল্যাম্পের ভেতরে পারদের মতো বিষাক্ত পদার্থ থাকে।\n• আইন: এই ল্যাম্পগুলোকেও বিপজ্জনক বর্জ্য হিসেবে গণ্য করা হয়।\n• করণীয়: এই ল্যাম্পগুলোকে না ভেঙে সাবধানে সংগ্রহ করতে হবে এবং অনুমোদিত ডিসপোজাল এজেন্সির কাছে পাঠাতে হবে।","importance":"পারদ একটি মারাত্মক নিউরোটক্সিন যা মানুষ এবং বন্যপ্রাণীর স্বাস্থ্যের জন্য অত্যন্ত ক্ষতিকর।","image_name":"/images/loader/haz78_lamp.webp","image_caption":"ল্যাম্প · পারদ"}],"image_name":"/images/loader/haz78_oil.webp","image_caption":"ট্রান্সফরমার অয়েল · বর্জ্য"}],"image_suggestion":"একটি ইনফোগ্রাফিক যেখানে তিনটি ভিন্ন ধরনের বিপজ্জনক বর্জ্য (ট্রান্সফরমার অয়েলের ড্রাম, পুরনো ব্যাটারি, ভাঙা CFL ল্যাম্প) এবং তাদের জন্য সঠিক ডিসপোজাল পদ্ধতি (যেমন রিসাইক্লিং চিহ্ন) দেখানো হয়েছে। প্রতিটি ভুল পদ্ধতির (যেমন মাটিতে তেল ফেলা) ওপর একটি লাল ক্রস চিহ্ন থাকবে।","pro_tip":{"title":"বিশেষ প্রো টিপস (Pro Tips)","content":["১. স্পিল কিট (Spill Kit) ব্যবহার করুন: তেল বদলানোর সময় বা তেল লিক হলে, মাটি দূষণ আটকাতে একটি ''স্পিল কিট'' ব্যবহার করুন। এর মধ্যে তেল শোষণকারী প্যাড, বুম এবং অন্যান্য সামগ্রী থাকে।","২. বর্জ্যকে আলাদা রাখুন: বিপজ্জনক বর্জ্যকে (যেমন তেল-মাখা কাপড়) সাধারণ বর্জ্য থেকে আলাদা করে নির্দিষ্ট ডাস্টবিনে ফেলুন।","৩. কোম্পানির নীতি জানুন: প্রতিটি কোম্পানিরই পরিবেশগত ব্যবস্থাপনার (Environmental Management) একটি নির্দিষ্ট নীতি বা পলিসি থাকে। সেই নীতি সম্পর্কে জানুন এবং অনুসরণ করুন।","৪. সবুজ বিকল্প: সম্ভব হলে, পরিবেশ-বান্ধব বিকল্প ব্যবহার করতে উৎসাহিত করুন, যেমন— بایوডিগ্রেডেবল ট্রান্সফরমার অয়েল বা এলইডি লাইট।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","myths":[{"myth":"একটু তেল মাটিতে পড়লে কিছু হয় না, মাটি তো শুষে নেয়।","reality":"ভুল। মাটি তেলকে শুষে নিলেও, তেল মাটির গভীরে গিয়ে ভূগর্ভস্থ জলকে (Groundwater) দূষিত করে, যা আমাদের পানীয় জলের একটি প্রধান উৎস। এটি একটি দীর্ঘস্থায়ী ক্ষতি।"},{"myth":"পরিবেশের আইন তো শুধু বড় বড় ফ্যাক্টরির জন্য, আমাদের এসব মানার দরকার নেই।","reality":"না। এই আইনগুলো যে কোনো ব্যক্তি বা সংস্থার জন্য প্রযোজ্য যারা বিপজ্জনক বর্জ্য তৈরি করেন। নিয়ম লঙ্ঘন করলে ব্যক্তিগতভাবে এবং কোম্পানি—উভয়েরই বড় আকারের জরিমানা হতে পারে।"}],"image_name":"/images/loader/haz78_myth.webp","image_caption":"মিথ বনাম বাস্তবতা · বর্জ্য"},"advanced_section":{"title":"এর পেছনের বৈশ্বিক দিক","facts":[{"title":"স্টকহোম কনভেনশন (Stockholm Convention)","content":"PCB (Polychlorinated Biphenyls) হলো একটি Persistent Organic Pollutant (POP), অর্থাৎ এটি পরিবেশে সহজে নষ্ট হয় না এবং খাদ্য শৃঙ্খলের মাধ্যমে প্রাণী ও মানুষের শরীরে জমা হতে থাকে। ভারত সহ বিশ্বের বেশিরভাগ দেশ ''স্টকহোম কনভেনশন''-এ স্বাক্ষর করেছে, যা PCB-র মতো ক্ষতিকারক রাসায়নিকের ব্যবহার এবং উৎপাদন বন্ধ করার জন্য একটি আন্তর্জাতিক চুক্তি। পুরনো ট্রান্সফরমার অয়েলের সঠিক নিষ্পত্তি এই চুক্তিরই একটি অংশ।"},{"title":"আইএসও ১৪০০১ (ISO 14001)","content":"এটি এনভায়রনমেন্টাল ম্যানেজমেন্ট সিস্টেমের জন্য একটি আন্তর্জাতিক স্ট্যান্ডার্ড। যে কোম্পানিগুলো ISO 14001 সার্টিফায়েড, তারা পরিবেশগত আইন মানার এবং ক্রমাগত তাদের পরিবেশগত পারফর্ম্যান্স উন্নত করার জন্য প্রতিশ্রুতিবদ্ধ। আপনার কোম্পানি এই সার্টিফায়েড কিনা তা জেনে নিতে পারেন।"}]}}'::jsonb,
  version = COALESCE(version, 0) + 1
WHERE id = '7.8' AND language = 'bn';

-- Lesson 7.9
UPDATE training_chapters
SET
  content = '{"level_id":"7.9","badge_name":"আইন কি বলে?","level_title":"গ্রাহকের অধিকার এবং লাইনম্যানের দায়িত্ব","mission_briefing":"আপনি যখন একজন গ্রাহকের বাড়িতে কাজ করতে যান, তখন আপনি শুধু একজন টেকনিশিয়ান নন, আপনি আপনার কোম্পানির একজন প্রতিনিধি। আইন এবং নিয়মাবলী গ্রাহকদের কিছু নির্দিষ্ট অধিকার দিয়েছে, এবং সেই অধিকারকে সম্মান করা আপনার পেশাগত দায়িত্ব। এই লেভেলের মিশন হলো, গ্রাহকের প্রধান অধিকারগুলো জানা এবং একজন পেশাদার প্রতিনিধি হিসেবে নিজের দায়িত্বের সীমা বোঝা।","sections":[{"title":"পরিষেবা এবং সম্মানের ভারসাম্য","points":[{"item_name":"১. গ্রাহকের প্রধান অধিকার","specifications":"ইলেকট্রিসিটি অ্যাক্ট এবং সাপ্লাই কোড অনুযায়ী, একজন গ্রাহকের কিছু মৌলিক অধিকার আছে, যেমন:\n• নিরবচ্ছিন্ন বিদ্যুৎ পাওয়ার অধিকার (কিছু ব্যতিক্রম ছাড়া)।\n• সঠিক এবং সময়মতো বিল পাওয়ার অধিকার।\n• অভিযোগ নথিভুক্ত করার এবং তার দ্রুত সমাধান পাওয়ার অধিকার।\n• নতুন সংযোগের জন্য আবেদন করার অধিকার।\n• কাজের সময় আপনার কাছ থেকে পরিচয়পত্র (Identity Card) দেখার অধিকার।","importance":"এই অধিকারগুলো জানা আপনাকে গ্রাহকের সাথে আত্মবিশ্বাসের সাথে এবং সঠিকভাবে संवाद করতে সাহায্য করবে।","image_name":"/images/loader/cust79_rights.webp","image_caption":"গ্রাহকের অধিকার"},{"item_name":"২. আপনার প্রবেশের অধিকার এবং তার সীমা","specifications":"• আইন: আইন অনুযায়ী, বিদ্যুৎ কোম্পানির অনুমোদিত প্রতিনিধি (অর্থাৎ আপনি) মিটার রিডিং, পরিদর্শন, পরীক্ষা, বা মেরামত করার জন্য গ্রাহকের প্রাঙ্গণে প্রবেশ করতে পারেন।\n• শর্ত: তবে, এই প্রবেশের জন্য আপনাকে একটি নির্দিষ্ট সময়ের আগে গ্রাহককে একটি যুক্তিসঙ্গত নোটিশ (Reasonable Notice) দিতে হবে (জরুরি অবস্থা ছাড়া)। আপনি জোর করে বা গ্রাহকের অনুমতি ছাড়া তার বাড়িতে প্রবেশ করতে পারেন না।","importance":"আপনার কাজের অধিকার এবং গ্রাহকের ব্যক্তিগত গোপনীয়তার অধিকার—দুটির মধ্যেই ভারসাম্য বজায় রাখাটা জরুরি।","image_name":"/images/loader/cust79_entry.webp","image_caption":"প্রবেশের অধিকার · সীমা"},{"item_name":"৩. আপনার দায়িত্ব: একজন পেশাদার প্রতিনিধি","specifications":"গ্রাহকের বাড়িতে কাজ করার সময় আপনার দায়িত্ব হলো:\n• পরিচয়পত্র দেখানো: গ্রাহক চাওয়ার আগেই আপনার কোম্পানির পরিচয়পত্র দেখান।\n• ভদ্র ব্যবহার: গ্রাহকের সাথে ভদ্র এবং সম্মানজনকভাবে কথা বলুন।\n• কাজের ব্যাখ্যা: আপনি কী কাজ করতে এসেছেন এবং কেন, তা সহজ ভাষায় গ্রাহককে বোঝান।\n• সুরক্ষা নিশ্চিত করা: আপনার কাজের কারণে যেন গ্রাহকের বা তার সম্পত্তির কোনো ক্ষতি না হয়, সেদিকে খেয়াল রাখুন।\n• কাজ শেষে পরিচ্ছন্নতা: কাজ শেষে আপনার কাজের জায়গাটি পরিষ্কার করে দিন।","importance":"আপনার আচরণ এবং কাজের গুণমানই গ্রাহকের মনে আপনার কোম্পানি সম্পর্কে ধারণা তৈরি করে।","image_name":"/images/loader/cust79_conduct.webp","image_caption":"পেশাদার প্রতিনিধি"}],"image_name":"/images/loader/cust79_rights.webp","image_caption":"গ্রাহকের অধিকার"}],"image_suggestion":"একটি ছবি যেখানে একজন ইউনিফর্ম পরা লাইনম্যান তার পরিচয়পত্র দেখাচ্ছেন এবং একজন গ্রাহক হাসিমুখে তার সাথে কথা বলছেন। ছবির পরিবেশটি পেশাদার এবং বন্ধুত্বপূর্ণ হবে।","pro_tip":{"title":"বিশেষ প্রো টিপস (Pro Tips)","content":["১. বিতর্ক এড়িয়ে চলুন: যদি কোনো গ্রাহক উত্তেজিত বা রাগান্বিত থাকেন, তবে তার সাথে তর্কে জড়াবেন না। শান্তভাবে তার কথা শুনুন এবং তাকে বোঝান যে আপনি তার সমস্যা সমাধানের জন্যই এসেছেন।","২. প্রতিশ্রুতি দেবেন না: যদি কোনো সমস্যার সমাধান আপনার হাতে না থাকে (যেমন ট্রান্সফরমার বদলানো), তবে সেই বিষয়ে কোনো মিথ্যা প্রতিশ্রুতি দেবেন না। গ্রাহককে সঠিক তথ্য দিন এবং বলুন যে আপনি বিষয়টি আপনার ঊর্ধ্বতন কর্তৃপক্ষকে জানাবেন।","৩. মহিলাদের সম্মান: যদি বাড়িতে কোনো মহিলা একা থাকেন, তবে অতিরিক্ত সম্মান এবং পেশাদারিত্বের পরিচয় দিন। সম্ভব হলে, অন্য কোনো সহকর্মী বা স্থানীয় ব্যক্তিকে সাক্ষী হিসেবে সাথে রাখুন।","৪. ডকুমেন্টেশন: কোনো বড় কাজ বা মিটার বদলানোর সময়, গ্রাহকের স্বাক্ষর সহ একটি জব শিট (Job Sheet) পূরণ করুন। এটি আপনার কাজের একটি প্রমাণ।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","myths":[{"myth":"গ্রাহকের বাড়িতে কাজ করতে এসেছি, তার মানে আমি যেকোনো জায়গায় যেতে পারি এবং যেকোনো কিছু করতে পারি।","reality":"ভুল। আপনার প্রবেশের অধিকার শুধুমাত্র আপনার কাজের সাথে সম্পর্কিত জায়গার (যেমন মিটার বক্স, ওয়্যারিং-এর রুট) মধ্যেই সীমাবদ্ধ। গ্রাহকের ব্যক্তিগত গোপনীয়তাকে সম্মান করা আপনার দায়িত্ব।"},{"myth":"গ্রাহক তো কিছুই বোঝেন না, তাকে যা-খুশি বুঝিয়ে দিলেই হলো।","reality":"এটি একটি অপেশাদার এবং ভুল মনোভাব। একজন সৎ পেশাদার হিসেবে, আপনার দায়িত্ব হলো গ্রাহককে সঠিক এবং স্বচ্ছ তথ্য দেওয়া। আপনার সততাই কোম্পানির সম্মান বাড়ায়।"}],"image_name":"/images/loader/cust79_myth.webp","image_caption":"মিথ বনাম বাস্তবতা · গ্রাহক"},"advanced_section":{"title":"এর পেছনের আইনি দিক","facts":[{"title":"স্ট্যান্ডার্ডস অফ পারফর্ম্যান্স (Standards of Performance - SoP)","content":"প্রতিটি রাজ্যের ইলেকট্রিসিটি রেগুলেটরি কমিশন (Electricity Regulatory Commission) বিদ্যুৎ কোম্পানিগুলোর জন্য একটি ''স্ট্যান্ডার্ডস অফ পারফর্ম্যান্স'' বা পরিষেবার মানদণ্ড নির্ধারণ করে দেয়। এতে লেখা থাকে যে একটি নতুন সংযোগ কতদিনের মধ্যে দিতে হবে, একটি ফল্টের অভিযোগ কত ঘন্টার মধ্যে সমাধান করতে হবে, ইত্যাদি। এই মানদণ্ড পূরণ করতে না পারলে কোম্পানির জরিমানা হতে পারে।"},{"title":"কনজিউমার গ্রিভান্স রিড্রেসাল ফোরাম (CGRF - Consumer Grievance Redressal Forum)","content":"যদি কোনো গ্রাহক বিদ্যুৎ কোম্পানির পরিষেবাতে সন্তুষ্ট না হন, তবে তিনি CGRF বা গ্রাহক অভিযোগ নিষ্পত্তি ফোরামে অভিযোগ জানাতে পারেন। এটি একটি আধা-বিচারবিভাগীয় সংস্থা যা গ্রাহকের অভিযোগ শোনে এবং তার সমাধান করে। আপনার কাজের গুণমান এবং আচরণ এই ফোরামে পর্যালোচিত হতে পারে।"}]}}'::jsonb,
  version = COALESCE(version, 0) + 1
