  content = '{"level_id":"7.10","badge_name":"আইন কি বলে?","level_title":"একজন ''সার্টিফায়েড'' লাইনম্যান: লাইসেন্স ও যোগ্যতার গুরুত্ব","mission_briefing":"বিদ্যুৎ-এর কাজ শুধু একটি চাকরি নয়, এটি একটি গুরুদায়িত্বপূর্ণ পেশা যার জন্য বিশেষ জ্ঞান এবং দক্ষতার প্রয়োজন। আইন অনুযায়ী, যে কেউ চাইলেই হাই-ভোল্টেজ লাইনে কাজ করতে পারে না। এর জন্য নির্দিষ্ট যোগ্যতা, প্রশিক্ষণ এবং অনেক ক্ষেত্রে একটি লাইসেন্সের প্রয়োজন হয়। এই ব্যাজের চূড়ান্ত মিশন হলো, একজন সাধারণ কর্মী থেকে একজন আইনত স্বীকৃত বা ''সার্টিফায়েড'' প্রফেশনাল হয়ে ওঠার পথ এবং তার গুরুত্ব সম্পর্কে জানা।","sections":[{"title":"দক্ষতা থেকে স্বীকৃতি: পেশাগত যাত্রার চূড়ান্ত ধাপ","points":[{"item_name":"১. আইনগত যোগ্যতা: কে বিদ্যুৎ-এর কাজ করতে পারেন?","specifications":"CEA রেগুলেশন অনুযায়ী, বিদ্যুৎ লাইনে কাজ করার জন্য একজন ব্যক্তিকে ''উপযুক্ত'' (Competent) হতে হবে। এর মানে হলো, তার বয়স ১৮ বছরের বেশি হতে হবে এবং তার বিদ্যুৎ লাইনে কাজ করার জন্য পর্যাপ্ত প্রশিক্ষণ এবং অভিজ্ঞতা থাকতে হবে, যাতে তিনি বিপদগুলো চিনতে পারেন এবং তা এড়াতে পারেন।","importance":"এর মানে হলো, আপনার কোম্পানি আপনাকে সঠিক প্রশিক্ষণ দিতে আইনত বাধ্য। প্রশিক্ষণ ছাড়া আপনাকে কোনো ঝুঁকিপূর্ণ কাজে পাঠানোটা আইনের লঙ্ঘন।","image_name":"/images/loader/cert710_competent.webp","image_caption":"উপযুক্ত ব্যক্তি · প্রশিক্ষণ"},{"item_name":"২. ওয়ার্কম্যান পারমিট বা লাইনম্যান লাইসেন্স","specifications":"ভারতের অনেক রাজ্যে, বিদ্যুৎ-এর তারের কাজ (Electrical Wiring) বা লাইন রক্ষণাবেক্ষণের কাজ করার জন্য রাজ্য সরকারের লাইসেন্সিং বোর্ড (State Electrical Licensing Board) থেকে একটি ''ওয়ার্কম্যান পারমিট'' বা লাইসেন্স নিতে হয়।\n• কীভাবে পাওয়া যায়: এর জন্য সাধারণত একটি নির্দিষ্ট শিক্ষাগত যোগ্যতা (যেমন ITI), নির্দিষ্ট বছরের কাজের অভিজ্ঞতা এবং একটি পরীক্ষা বা ইন্টারভিউ পাশ করতে হয়।","importance":"এই লাইসেন্সটি প্রমাণ করে যে আপনি কাজটি করার জন্য আইনত যোগ্য এবং দক্ষ। এটি আপনার পেশাগত মূল্য এবং विश्वसनीयता অনেক বাড়িয়ে দেয়। অনেক বড় কোম্পানি বা ঠিকাদারের কাজ পাওয়ার জন্য এটি একটি আবশ্যক শর্ত।","image_name":"/images/loader/cert710_licence.webp","image_caption":"ওয়ার্কম্যান পারমিট"},{"item_name":"৩. ক্রমাগত প্রশিক্ষণ এবং দক্ষতা বৃদ্ধি","specifications":"বিদ্যুৎ প্রযুক্তি ক্রমাগত পরিবর্তন হচ্ছে। নতুন সরঞ্জাম, নতুন সুরক্ষা নিয়ম এবং নতুন কাজের পদ্ধতি আসছে। একজন ভালো পেশাদার হিসেবে, আপনার দায়িত্ব হলো ক্রমাগত প্রশিক্ষণের মাধ্যমে নিজের জ্ঞান এবং দক্ষতাকে আপডেট রাখা।\n• উদাহরণ: লাইভ লাইন কাজের প্রশিক্ষণ, হাই-ভোল্টেজ কেবিল জয়েন্টিং-এর সার্টিফিকেশন, ফার্স্ট এইড এবং ফায়ার সেফটি ট্রেনিং।","importance":"ক্রমাগত শেখা আপনাকে শুধু আরও ভালো কর্মীই বানায় না, এটি আপনার ক্যারিয়ারে অগ্রগতির পথও খুলে দেয়। আপনি একজন সাধারণ লাইনম্যান থেকে একজন দক্ষ টেকনিশিয়ান, ফোরম্যান বা এমনকি সুপারভাইজারও হতে পারেন।","image_name":"/images/loader/cert710_train.webp","image_caption":"ক্রমাগত প্রশিক্ষণ"}],"image_name":"/images/loader/cert710_competent.webp","image_caption":"উপযুক্ত ব্যক্তি · প্রশিক্ষণ"}],"image_suggestion":"একজন লাইনম্যানের ছবি, যিনি গর্বের সাথে তার ''সার্টিফায়েড লাইনম্যান'' লাইসেন্স বা সার্টিফিকেটটি দেখাচ্ছেন। তার পেছনে একটি আধুনিক এবং সুশৃঙ্খল বিদ্যুৎ নেটওয়ার্কের ছবি থাকবে, যা তার দক্ষতার প্রতীক।","pro_tip":{"title":"বিশেষ প্রো টিপস (Pro Tips)","content":["১. আপনার লক্ষ্য স্থির করুন: আপনার ক্যারিয়ারের পরবর্তী ধাপ কী হবে তা নিয়ে ভাবুন। আপনার কি কোনো বিশেষ ক্ষেত্রে (যেমন কেবিল জয়েন্টিং) বিশেষজ্ঞ হওয়ার ইচ্ছা আছে? আপনার লক্ষ্য অনুযায়ী প্রশিক্ষণের খোঁজ করুন।","২. কোম্পানির প্রশিক্ষণের সুযোগ নিন: বিদ্যুৎ কোম্পানিগুলো প্রায়ই তাদের কর্মীদের জন্য বিভিন্ন প্রশিক্ষণের আয়োজন করে। এই সুযোগগুলো কখনো হাতছাড়া করবেন না।","৩. আপনার অভিজ্ঞতাকে নথিভুক্ত করুন: আপনি কী কী কাজ করেছেন, কোন কোন প্রকল্পে অংশ নিয়েছেন এবং কী কী প্রশিক্ষণ নিয়েছেন, তার একটি ব্যক্তিগত লগবুক বা ডায়েরি তৈরি করুন। এটি আপনার লাইসেন্স পাওয়ার বা চাকরির ইন্টারভিউ-এর সময় খুব কাজে দেবে।","৪. অন্যদের কাছ থেকে শিখুন: আপনার সিনিয়র বা অভিজ্ঞ সহকর্মীরা জ্ঞানের ভান্ডার। তাদের কাছ থেকে কাজ শিখতে এবং প্রশ্ন করতে কখনো লজ্জা পাবেন না।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","myths":[{"myth":"একবার কাজ শিখে গেলে আর নতুন করে শেখার কিছু নেই।","reality":"ভুল। প্রযুক্তি এবং সুরক্ষার নিয়ম প্রতিদিন পাল্টাচ্ছে। যে কর্মী সময়ের সাথে নিজেকে আপডেট করেন না, তিনি পিছিয়ে পড়েন এবং তার কাজের মান ও সুরক্ষার স্তরও কমে যায়। শেখার কোনো শেষ নেই।"},{"myth":"লাইসেন্স বা সার্টিফিকেট তো শুধু কাগজে দেখানোর জন্য, আসল তো হলো কাজের অভিজ্ঞতা।","reality":"অভিজ্ঞতা অপরিহার্য, কিন্তু লাইসেন্স বা সার্টিফিকেট আপনার সেই অভিজ্ঞতাকে একটি আনুষ্ঠানিক এবং আইনগত স্বীকৃতি দেয়। এটি প্রমাণ করে যে আপনি শুধু কাজটি করতে পারেন তাই নয়, আপনি কাজটি সঠিক এবং সুরক্ষিতভাবে করার জন্য প্রশিক্ষিত।"}],"image_name":"/images/loader/cert710_myth.webp","image_caption":"মিথ বনাম বাস্তবতা · লাইসেন্স"},"advanced_section":{"title":"এর পেছনের পেশাগত দিক","facts":[{"title":"ন্যাশনাল স্কিল কোয়ালিফিকেশন ফ্রেমওয়ার্ক (NSQF)","content":"ভারত সরকার বিভিন্ন পেশার জন্য একটি ন্যাশনাল স্কিল কোয়ালিফিকেশন ফ্রেমওয়ার্ক তৈরি করেছে, যা দক্ষতার বিভিন্ন স্তর (Level 1, 2, 3...) নির্ধারণ করে। পাওয়ার সেক্টরের জন্যও এই ধরনের যোগ্যতা কাঠামো (Qualification Packs - QPs) আছে। এই QP অনুযায়ী প্রশিক্ষণ নিলে এবং পরীক্ষা পাশ করলে আপনি ভারত সরকার দ্বারা স্বীকৃত একটি সার্টিফিকেট পান, যা সারা দেশে বৈধ।"},{"title":"কন্টিনিউইং প্রফেশনাল ডেভেলপমেন্ট (CPD - Continuing Professional Development)","content":"এটি একটি ধারণা যা অনুযায়ী, একজন পেশাদারকে তার পুরো কর্মজীবনে ক্রমাগত শিখতে এবং নিজের দক্ষতাকে উন্নত করতে হয়। অনেক পেশায়, লাইসেন্স नवीकरण করার জন্য নির্দিষ্ট সংখ্যক CPD পয়েন্ট অর্জন করা বাধ্যতামূলক, যা প্রমাণ করে যে ব্যক্তিটি তার ক্ষেত্রের নতুন অগ্রগতির সাথে পরিচিত আছেন।"}]}}'::jsonb,
  version = COALESCE(version, 0) + 1
WHERE id = '7.10' AND language = 'bn';
